g width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n            <line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\" />\n            <line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\" />\n          </svg>\n        </button>\n\n        <!-- 物品图片 -->\n        <div class=\"detail-img-area\">\n          <img\n            :src=\"itemImage\"\n            :alt=\"item.name\"\n            class=\"detail-img\"\n          />\n        </div>\n\n        <!-- 物品信息 -->\n        <div class=\"detail-info\">\n          <div class=\"detail-name\">{{ item.name }}</div>\n          <div v-if=\"itemKeywords\" class=\"detail-keywords\">{{ itemKeywords }}</div>\n          <div class=\"detail-desc\">{{ item.description }}</div>\n\n          <!-- 可交互操作列表 -->\n          <div v-if=\"interactionList.length > 0\" class=\"detail-interactions\">\n            <div class=\"detail-section-title\">可用操作</div>\n            <div\n              v-for=\"(action, idx) in interactionList\"\n              :key=\"idx\"\n              class=\"detail-action\"\n              @click=\"onActionClick(action)\"\n            >\n              <span class=\"action-dot\"></span>\n              <span class=\"action-name\">{{ action.name }}</span>\n              <svg class=\"action-arrow\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <polyline points=\"9 18 15 12 9 6\"/>\n              </svg>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </Transition>\n</template>\n\n<script setup lang=\"ts\">\nimport type { ItemData } from '../schema';\nimport { ITEM_IMAGES, ITEM_KEYWORDS, DEFAULT_ITEM_IMAGE } from '../items';\n\nconst props = defineProps<{\n  item: ItemData | null;\n}>();\n\nconst emit = defineEmits<{\n  close: [];\n}>();\n\nconst itemImage = computed(() => {\n  if (!props.item) return DEFAULT_ITEM_IMAGE;\n  return ITEM_IMAGES[props.item.name] || DEFAULT_ITEM_IMAGE;\n});\n\nconst itemKeywords = computed(() => {\n  if (!props.item) return '';\n  return ITEM_KEYWORDS[props.item.name] || '';\n});\n\ninterface ActionInfo {\n  name: string;\n  instruction: string;\n}\n\nconst interactionList = computed<ActionInfo[]>(() => {\n  if (!props.item?.interactions) return [];\n  return props.item.interactions.flatMap(record => {\n    return Object.entries(record).map(([name, instruction]) => ({ name, instruction }));\n  });\n});\n\n/**\n * 点击操作：将玩家意图填入酒馆输入框并发送\n *\n * 密室交互脚本使用 registerFunctionTool 注册了 interact 工具，\n * AI 模型会自动识别用户意图并调用对应的 function tool。\n * 玩家只需发送简洁的意图描述即可。\n */\nfunction onActionClick(action: ActionInfo) {\n  try {\n    // 构建简洁的用户意图\n    const userInput = `${action.name}${props.item!.name}`;\n\n    // 通过 jQuery 操作酒馆输入框\n    const $textarea = $('#send_textarea');\n    if ($textarea.length > 0) {\n      // 填入文本\n      $textarea.val(userInput);\n      // 触发 input 事件让酒馆感知到内容变化\n      $textarea.trigger('input');\n\n      // 短暂延迟后点击发送按钮\n      setTimeout(() => {\n        const $sendBtn = $('#send_but');\n        if ($sendBtn.length > 0) {\n          $sendBtn.trigger('click');\n        }\n      }, 100);\n\n      // 关闭详情面板\n      emit('close');\n\n      toastr.info(`正在执行：${action.name} → ${props.item!.name}`, '', { timeOut: 2000 });\n    } else {\n      console.warn('[始物品展示] 未找到酒馆输入框');\n      toastr.warning('未找到酒馆输入框');\n    }\n  } catch (err) {\n    console.error('[始物品展示] 操作执行失败:', err);\n    toastr.error('操作执行失败');\n  }\n}\n</script>\n\n<style scoped>\n.detail-overlay {\n  position: fixed;\n  left: 0;\n  top: 0;\n  width: 100vw;\n  height: 100vh;\n  background: rgba(0, 0, 0, 0.8);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 10000;\n  backdrop-filter: blur(6px);\n  pointer-events: auto;\n  padding: 16px;\n  box-sizing: border-box;\n}\n\n.detail-card {\n  position: relative;\n  max-width: 460px;\n  width: 100%;\n  max-height: calc(100vh - 32px);\n  overflow-y: auto;\n  background: linear-gradient(145deg, rgba(18, 22, 35, 0.98), rgba(12, 16, 28, 0.98));\n  border-radius: 14px;\n  border: 1px solid rgba(200, 170, 110, 0.15);\n  box-shadow:\n    0 20px 60px rgba(0, 0, 0, 0.5),\n    0 0 30px rgba(200, 170, 110, 0.05);\n  margin: auto;\n}\n\n.detail-card::-webkit-scrollbar {\n  width: 3px;\n}\n\n.detail-card::-webkit-scrollbar-thumb {\n  background: rgba(200, 170, 110, 0.2);\n  border-radius: 2px;\n}\n\n.detail-close {\n  position: absolute;\n  top: 10px;\n  right: 10px;\n  z-index: 2;\n  width: 28px;\n  height: 28px;\n  border-radius: 50%;\n  border: none;\n  background: rgba(0, 0, 0, 0.5);\n  color: rgba(255, 255, 255, 0.6);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: all 0.2s;\n}\n\n.detail-close:hover {\n  background: rgba(0, 0, 0, 0.7);\n  color: #fff;\n}\n\n.detail-img-area {\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  overflow: hidden;\n  background: rgba(0, 0, 0, 0.3);\n  border-radius: 14px 14px 0 0;\n}\n\n.detail-img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  display: block;\n}\n\n.detail-info {\n  padding: 18px 22px 22px;\n}\n\n.detail-name {\n  font-size: 18px;\n  font-weight: 600;\n  color: rgba(255, 255, 255, 0.92);\n  margin-bottom: 4px;\n  letter-spacing: 0.5px;\n}\n\n.detail-keywords {\n  font-size: 12px;\n  color: rgba(200, 170, 110, 0.6);\n  margin-bottom: 10px;\n  letter-spacing: 0.3px;\n}\n\n.detail-desc {\n  font-size: 14px;\n  color: rgba(255, 255, 255, 0.6);\n  line-height: 1.7;\n  margin-bottom: 16px;\n}\n\n.detail-interactions {\n  border-top: 1px solid rgba(255, 255, 255, 0.06);\n  padding-top: 14px;\n}\n\n.detail-section-title {\n  font-size: 11px;\n  font-weight: 600;\n  color: rgba(200, 170, 110, 0.7);\n  text-transform: uppercase;\n  letter-spacing: 1.5px;\n  margin-bottom: 10px;\n}\n\n.detail-action {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 12px;\n  border-radius: 8px;\n  background: rgba(255, 255, 255, 0.03);\n  margin-bottom: 6px;\n  transition: all 0.2s;\n  cursor: pointer;\n  border: 1px solid transparent;\n}\n\n.detail-action:hover {\n  background: rgba(200, 170, 110, 0.1);\n  border-color: rgba(200, 170, 110, 0.2);\n}\n\n.detail-action:active {\n  background: rgba(200, 170, 110, 0.15);\n  transform: scale(0.98);\n}\n\n.action-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: rgba(200, 170, 110, 0.5);\n  flex-shrink: 0;\n}\n\n.detail-action:hover .action-dot {\n  background: rgba(200, 170, 110, 0.8);\n}\n\n.action-name {\n  font-size: 14px;\n  font-weight: 500;\n  color: rgba(255, 255, 255, 0.8);\n  flex: 1;\n}\n\n.detail-action:hover .action-name {\n  color: rgba(255, 255, 255, 0.95);\n}\n\n.action-arrow {\n  color: rgba(255, 255, 255, 0.2);\n  flex-shrink: 0;\n  transition: color 0.2s, transform 0.2s;\n}\n\n.detail-action:hover .action-arrow {\n  color: rgba(200, 170, 110, 0.7);\n  transform: translateX(2px);\n}\n\n/* 过渡动画 */\n.detail-enter-active,\n.detail-leave-active {\n  transition: opacity 0.25s ease;\n}\n\n.detail-enter-active .detail-card,\n.detail-leave-active .detail-card {\n  transition: transform 0.25s ease;\n}\n\n.detail-enter-from,\n.detail-leave-to {\n  opacity: 0;\n}\n\n.detail-enter-from .detail-card {\n  transform: scale(0.92) translateY(10px);\n}\n\n.detail-leave-to .detail-card {\n  transform: scale(0.92) translateY(10px);\n}\n\n/* 手机端适配 */\n@media (max-width: 500px) {\n  .detail-overlay {\n    padding: 8px;\n  }\n\n  .detail-card {\n    max-width: 100%;\n    border-radius: 12px;\n  }\n\n  .detail-img-area {\n    aspect-ratio: 4 / 3;\n    border-radius: 12px 12px 0 0;\n  }\n\n  .detail-info {\n    padding: 14px 16px 16px;\n  }\n\n  .detail-name {\n    font-size: 15px;\n  }\n\n  .detail-keywords {\n    font-size: 11px;\n  }\n\n  .detail-desc {\n    font-size: 12px;\n  }\n\n  .action-name {\n    font-size: 13px;\n  }\n}\n</style>\n"],"sourceRoot":""}]);
